// Renders THIRD_PARTY.md from third-party.json's assets. The JSON is the record; the Markdown is a
// reading copy, regenerated by every build, so the two cannot drift.
import { writeFileSync } from 'node:fs';

const escape = (text) => String(text).replace(/\|/g, '\\|');

export function renderThirdPartyMarkdown(assets) {
  const lines = [
    '# Third-party assets',
    '',
    'Every model and surface under `apps/web/src/assets/` comes from a third party, under the licence',
    'named for it. This file is generated from `third-party.json` by `scripts/assets/build.mjs`; edit the',
    'plan (`scripts/assets/plan.json`) and rebuild instead of editing it.',
    '',
    'Each source was checked on its own page (not only the provider\'s general licence page) on the',
    'retrieval date. The sha256 of every downloaded source file is in `third-party.json`.',
    '',
    '| Id | Kind | Title | Author | Licence | Source | Retrieved |',
    '|---|---|---|---|---|---|---|',
  ];
  for (const a of assets) {
    lines.push(`| \`${a.id}\` | ${a.kind} | ${escape(a.title)} | ${escape(a.author)} | [${a.licence}](${a.licenceUrl}) | <${a.source}> | ${a.retrieved} |`);
  }
  lines.push('', '## Attribution', '');
  for (const a of assets) lines.push(`- \`${a.id}\`: ${a.attribution}`);
  lines.push('', '## Changes made', '');
  lines.push('The shipped files are modified copies. Every asset was resized, re-encoded (WebP) and, for models,');
  lines.push('simplified, quantised and recentred; the exact steps per asset are below.', '');
  for (const a of assets) {
    lines.push(`### \`${a.id}\``, '');
    for (const t of a.transforms) lines.push(`- ${t}`);
    lines.push('');
  }
  return `${lines.join('\n').trimEnd()}\n`;
}

export function writeThirdPartyMarkdown(file, assets) {
  writeFileSync(file, renderThirdPartyMarkdown(assets));
}
